def count_insertions_to_palindrome(s):
    n = len(s)
    count = 0
    for i in range(n):
        if s[i:] == s[i:][::-1]:
            count += i
            break
    for i in range(n-1, -1, -1):
        if s[:i+1] == s[:i+1][::-1]:
            count += n - i - 1
            break
    return count + 1

